"""FC27 market activity is generated by 659 independent club decisions."""
import sqlite3
import unittest

from world_fc27_market_schedule import (
    VERSION,FC27_SLOT_BASE,club_market_interest,fc27_market_slot,
    initialise_fc27_market_schedule,is_fc27_market)
from world_live_market import _stable,MARKET_MOMENTS


class ClubLedMarketTests(unittest.TestCase):
    def test_every_club_has_independent_non_forced_intent(self):
        ambitions=[45,65,87]
        def outcomes(window_seed,scenario):
            return {club for interval in range(len(MARKET_MOMENTS))
                for club in range(1,660)
                if club_market_interest(priority=ambitions[club%3]+10,
                    profile={"ambition_level":ambitions[club%3]},
                    draw=_stable(window_seed,interval,club,VERSION,"scout")%1000000,
                    activity_scale_qa=scenario)}
        baseline=outcomes("season-one",1)
        other=outcomes("another-window",1)
        expanded=outcomes("season-one",3)
        self.assertGreater(len(baseline),0)
        self.assertLess(len(baseline),659)
        self.assertNotEqual(baseline,other)
        self.assertGreater(len(expanded),len(baseline))
        # This is merely the set of participating clubs, not a target
        # count for the number of completed market transfers.

    def test_more_urgency_and_ambition_increases_interest_not_guarantees(self):
        a={"ambition_level":30}
        b={"ambition_level":95}
        weak=sum(club_market_interest(priority=0,profile=a,draw=i)
                 for i in range(0,1000000,1000))
        strong=sum(club_market_interest(priority=100,profile=b,draw=i)
                   for i in range(0,1000000,1000))
        self.assertGreater(strong,weak)
        self.assertLess(strong,1000)

    def test_each_club_and_interval_has_stable_non_colliding_checkpoint(self):
        slots={fc27_market_slot(index,club) for index in range(12)
               for club in range(1,660)}
        self.assertEqual(len(slots),12*659)
        self.assertGreater(min(slots),FC27_SLOT_BASE)
        self.assertEqual(fc27_market_slot(7,99),fc27_market_slot(7,99))
        with self.assertRaises(ValueError):
            fc27_market_slot(0,1000000)

    def test_planner_tables_are_persistable_and_idempotent(self):
        con=sqlite3.connect(":memory:")
        try:
            initialise_fc27_market_schedule(con)
            initialise_fc27_market_schedule(con)
            con.execute("""INSERT INTO world_fc27_market_intervals
                VALUES(3,2,659,12,1,'2026-08-01T12:00:00+00:00')""")
            con.execute("""INSERT INTO world_fc27_market_club_intents
                (window_id,interval_index,club_id,source_priority)
                VALUES(3,2,27,77)""")
            with self.assertRaises(sqlite3.IntegrityError):
                con.execute("""INSERT INTO world_fc27_market_club_intents
                    (window_id,interval_index,club_id,source_priority)
                    VALUES(3,2,27,77)""")
        finally:
            con.close()

    def test_older_worlds_never_enter_fc27_schedule(self):
        con=sqlite3.connect(":memory:")
        try:
            con.execute("""CREATE TABLE world_career_saves(
                career_id TEXT,dataset_id TEXT)""")
            con.execute("""INSERT INTO world_career_saves VALUES(
                'legacy','england-2026')""")
            self.assertFalse(is_fc27_market(con,career_id="legacy"))
        finally:
            con.close()

    def test_nothing_is_mathematically_fixed_to_112(self):
        from pathlib import Path
        text=Path("world_live_market.py").read_text()
        self.assertIn("if fc27_club_led:",text)
        self.assertIn("process_fc27_market_interval(",text)
        self.assertIn("else:\n            # IMMUTABLE older careers",text)
        from world_fc27_market_schedule import SCHEMA
        self.assertIn("active_clubs INTEGER",SCHEMA)


if __name__=="__main__":
    unittest.main()
